/**
 * Mind mapping plugin for TinyMCE
 *
 * Released under the MIT license.
 * Author: Ignacio Gros (http://gros.es/) for http://exelearning.net/ 
 *
 * The editor (editor/) is built with Mind Elixir (https://github.com/SSShooter/mind-elixir-core)
 * modern-screenshot (https://github.com/qq15725/modern-screenshot) and
 * @ateeducacion/mind-elixir-export-mermaid, all under the MIT license. The author stores each
 * map as a PNG or as Mermaid code, which $exe.mermaid draws as SVG, plus the map's JSON to
 * edit it again.
 * Maps made with the previous editor, mindmaps (https://github.com/drichard/mindmaps), by
 * David Richard, are converted when they are opened (editor/src/storedMindmap.ts).
 *
 * Plugin icons by Google (https://material.io/tools/icons/), available under the Apache license version 2.0. (http://www.apache.org/licenses/LICENSE-2.0)
 *
 * Loading icon: http://ajaxload.info/
 */
tinymce.PluginManager.add('exemindmap', function (editor, url) {

    let $ = tinymce.dom.DomQuery;

    let labelInstructions = '';


    function hideElements() {
        let divMain = $('div.tox-form').eq(0);

        let divInstructions = divMain.children().eq(0);
        labelInstructions = divInstructions.children().eq(0);
        tinymce.DOM.setAttrib(labelInstructions, 'id', 'mindmapImgInstructions');

        let divDiagram = divMain.children().eq(1);
        tinymce.DOM.setAttrib(divDiagram.children().eq(0), 'id', 'mindmapDiagram');
        divDiagram.hide();

        let divCode = divMain.children().eq(2);
        let textareaCode = divCode.children().eq(0);
        tinymce.DOM.setAttrib(textareaCode, 'id', 'mindmapCode');
        divCode.hide();

        let divImgToSave = divMain.children().eq(3);
        tinymce.DOM.setAttrib(divImgToSave.children().eq(0), 'id', 'mindmapImgToSave');
        divImgToSave.hide();
        divMain.children().eq(4).hide(); // mindmapImgSize

        let divEditor = divMain.children().eq(5);
        let buttonEditor = divEditor.children().eq(0);
        tinymce.DOM.setStyle(buttonEditor, 'width', '100%');

        labelInstructions.text(eXeMediaPluginDialog.actualImgInstructions);

    }

    function closeMindmap() {
        tinymce.activeEditor.windowManager.confirm('Do you want to do something?', (state) => {
            state ? editor.windowManager.close() : false;
        });
    }

    function getPreviousValues() {

        // Get the previous values (the selection can be any element inside the map)
        var elm = editor.selection.getNode();
        elm = elm && elm.closest ? elm.closest(".exe-mind-map") : null;
        if (elm) {
            var e = $(elm);
            var title = e.find('.title');
            var code = e.find(".exe-mindmap-code");
            // A map is a PNG (every legacy map) or Mermaid code
            if (code.length == 1) {
                var img = e.find("img");
                var pre = e.find("pre.mermaid");
                eXeMediaPluginDialog.actualFormat = pre.length == 1 ? "svg" : "png";
                eXeMediaPluginDialog.actualDiagram = pre.length == 1 ? pre.text() : "";
                if (img.length == 1) {
                    eXeMediaPluginDialog.actualImgToSave = img.attr("src") || "";
                    eXeMediaPluginDialog.actualImgSize = (img.attr("width") || "") + "x" + (img.attr("height") || "");
                }
                eXeMediaPluginDialog.mode = "edit";
                eXeMediaPluginDialog.actualImgInstructions = _("You can edit the mind map...");
                var data = code.html();
                eXeMediaPluginDialog.actualCode = data;
                top.mindmapEditor.data = data;
                if (title.length == 1) {
                    eXeMediaPluginDialog.actualMindMapTitle = title.text();
                    eXeMediaPluginDialog.actualMindMapCaption = !e.find("figcaption").hasClass("sr-av");
                } else {
                    eXeMediaPluginDialog.actualMindMapTitle = e.find("img").attr("alt") || "";
                    eXeMediaPluginDialog.actualMindMapCaption = false;
                }
            }
        }
    };

    eXeMediaPluginDialog = {

        actualImgInstructions: _("Use the editor to create a new mind map..."),
        actualCode: '',
        actualDiagram: '',
        actualImgToSave: '',
        actualImgSize: '',
        actualFormat: 'png',
        actualMindMapTitle: '',
        actualMindMapCaption: true,


        getInitialData: function () {
            let data = {
                mindmapDiagram: eXeMediaPluginDialog.actualDiagram,
                mindmapCode: eXeMediaPluginDialog.actualCode,
                mindmapImgToSave: eXeMediaPluginDialog.actualImgToSave,
                mindmapImgSize: eXeMediaPluginDialog.actualImgSize,
                mindmapTitle: eXeMediaPluginDialog.actualMindMapTitle,
                mindmapCaption: eXeMediaPluginDialog.actualMindMapCaption,
            }
            return data;
        },

        setDefaultData: function () {
            eXeMediaPluginDialog.actualImgInstructions = _("Use the editor to create a new mind map...");
            eXeMediaPluginDialog.actualCode = '';
            eXeMediaPluginDialog.actualDiagram = '';
            eXeMediaPluginDialog.actualImgToSave = '';
            eXeMediaPluginDialog.actualImgSize = '';
            eXeMediaPluginDialog.actualFormat = 'png';
            eXeMediaPluginDialog.actualMindMapTitle = '';
            eXeMediaPluginDialog.actualMindMapCaption = true;
            eXeMediaPluginDialog.mode = 'new';
        },

        mode: "new", // new or edit

        openDialog: function () {

            // Contants
            top.mindmapEditor = {
                editor: "",
                data: "",
                closeConfirmed: false,
                tinymce: editor // this plugin's editor: an iDevice can have several TinyMCE instances
            }

            getPreviousValues();

            // Open the dialog
            win = editor.windowManager.open({
                title: _('Mind map'),
                body: {
                    type: 'panel',
                    items: [
                        {
                            type: 'label',
                            name: 'mindmapImgInstructions',
                            label: '',
                            items: []
                        },
                        {
                            type: 'textarea',
                            name: 'mindmapDiagram',
                        },
                        {
                            type: 'textarea',
                            name: 'mindmapCode',
                        },
                        {
                            type: 'input',
                            name: 'mindmapImgToSave',
                        },
                        {
                            type: 'input',
                            name: 'mindmapImgSize',
                        },
                        {
                            type: 'button',
                            name: 'mindmapEditorButton',
                            primary: true,
                            text: _("Open the mind map editor"),
                        },
                        {
                            type: 'input',
                            name: 'mindmapTitle',
                            label: _('Descriptive title')
                        },
                        {
                            type: 'checkbox',
                            name: 'mindmapCaption',
                            label: _("Show the title under the image")
                        },
                        {
                            // TinyMCE 5 has no radio buttons: native ones, read in onSubmit
                            type: 'htmlpanel',
                            html: eXeMediaPluginDialog.formatOptions()
                        }
                    ]
                },
                buttons: [
                    {
                        type: 'cancel',
                        name: 'cancel',
                        text: 'Cancel'
                    },
                    {
                        type: 'submit',
                        name: 'save',
                        text: 'Save',
                        primary: true
                    }
                ],
                initialData: eXeMediaPluginDialog.getInitialData(),
                onAction: function (api, details) {
                    if (details.name === 'mindmapEditorButton') {
                        // Determine URL based on mode: static vs server.
                        // In server mode we MUST go through composeUrl() so that BASE_PATH
                        // is prepended; emitting a bare "/api/..." URL 404s behind any
                        // reverse proxy that only mounts the BASE_PATH namespace (issue #1802).
                        var editorUrl = (window.eXeLearning && window.eXeLearning.app && typeof window.eXeLearning.app.composeUrl === 'function')
                            ? window.eXeLearning.app.composeUrl('/api/exemindmap-editor/index.html')
                            : '/api/exemindmap-editor/index.html';
                        var config = window.eXeLearning?.config;
                        if (typeof config === 'string') {
                            try { config = JSON.parse(config); } catch(e) { config = null; }
                        }
                        // Check for static mode, offline installation, global flag, or Electron
                        if (config?.isStaticMode || config?.isOfflineInstallation || window.__EXE_STATIC_MODE__ || window.electronAPI) {
                            // Use RELATIVE path (./libs/...) which works regardless of subdirectory depth
                            // The browser resolves ./libs/... relative to the current document location
                            // e.g., at /dist/static/index.html → ./libs/... resolves to /dist/static/libs/...
                            // e.g., at /index.html → ./libs/... resolves to /libs/...
                            editorUrl = "./libs/tinymce_5/js/tinymce/plugins/exemindmap/editor/index.html";
                        }
                        editor.windowManager.openUrl({
                            title: _('Editor'),
                            url: editorUrl,
                        });

                        let divDialog = $('div.tox-dialog').eq(1);
                        tinymce.DOM.setAttrib(divDialog, 'id', 'interactiveVideoEditor');

                        let closeButton = divDialog.children().eq(0).children().eq(2);
                        tinymce.DOM.setAttribs(closeButton, { 'id': 'closebutton', });
                    }
                },
                onSubmit: function (api) {

                    var values = api.getData();
                    eXeMediaPluginDialog.actualCode = values.mindmapCode;
                    eXeMediaPluginDialog.actualMindMapTitle = values.mindmapTitle;
                    eXeMediaPluginDialog.actualMindMapCaption = values.mindmapCaption;

                    // The editor sets the code and both views when it saves; an existing map
                    // starts with its code and the view it was stored as
                    var code = eXeMediaPluginDialog.actualCode;
                    if (code.indexOf('{') != 0) {
                        editor.windowManager.alert(_('Please create a mind map.'));
                        return false;
                    }
                    var svg = eXeMediaPluginDialog.selectedFormat() == 'svg';
                    var diagram = values.mindmapDiagram;
                    var img = values.mindmapImgToSave;
                    if (svg ? diagram.indexOf('mindmap') != 0 : img == '') {
                        editor.windowManager.alert(_('Open the mind map editor and save the map to change its format.'));
                        return false;
                    }

                    var title = eXeMediaPluginDialog.stripHtml(eXeMediaPluginDialog.actualMindMapTitle).trim();

                    if (title == "") {
                        editor.windowManager.alert(_('Please provide a title.'));
                        return false;
                    }

                    var escapedTitle = eXeMediaPluginDialog.escapeHtml(title);
                    var view, figureStyle = '', figcaption = '';
                    if (svg) {
                        // Mermaid source, which $exe.mermaid draws as SVG. Without a visible caption
                        // the title stays in it, so the diagram keeps an accessible name.
                        view = '<pre class="mermaid">' + eXeMediaPluginDialog.escapeHtml(diagram) + '</pre>';
                        var captionClass = eXeMediaPluginDialog.actualMindMapCaption ? 'figcaption' : 'figcaption sr-av';
                        figcaption = '<figcaption class="' + captionClass + '"><span class="title"><em>' + escapedTitle + '</em></span></figcaption>';
                    } else {
                        // The image's alt names it; the caption is optional, as in legacy maps
                        var size = String(values.mindmapImgSize).split('x');
                        var w = Math.round(size[0]) || 600;
                        var h = Math.round(size[1]) || 400;
                        figureStyle = ' style="width: ' + w + 'px;"';
                        view = '<img src="' + eXeMediaPluginDialog.escapeHtml(img) + '" width="' + w + '" height="' + h + '" alt="' + escapedTitle + '">';
                        if (eXeMediaPluginDialog.actualMindMapCaption) {
                            figcaption = '<figcaption class="figcaption"><span class="title"><em>' + escapedTitle + '</em></span></figcaption>';
                        }
                    }

                    // `code` comes from the editor already escaped
                    var content = `
                    <div class="exe-mind-map">
                        <figure class="exe-figure exe-image position-center"${figureStyle}>
                            ${view}
                            ${figcaption}
                        </figure>
                        <p class="exe-mindmap-code">${code}</p>
                    </div>
                    `;

                    if (eXeMediaPluginDialog.mode == "edit") {
                        var node = editor.selection.getNode();
                        let oldImage = node.closest(".exe-mind-map");
                        // Replace the whole map, whichever view it had
                        $(oldImage).remove();
                    } else {
                        content += "..."; // Add a P after the map    
                    }

                    // Add the new content
                    editor.execCommand('mceInsertContent', false, content, { skip_undo: 1 });

                    eXeMediaPluginDialog.showMindMapsTitles(editor);

                    editor.windowManager.close();

                    return false;

                },
                onClose: function () {
                    eXeMediaPluginDialog.setDefaultData();
                }

            });

            hideElements();

            top.mindmapEditor.pluginDialog = win;

        }, // openDialog

        showMindMapsTitles: function (editor) {
            var d = editor.getDoc();
            jQuery("HEAD #eXeMediaPluginDialogCSS", d).remove();
            var s = '<style type="text/css" id="eXeMediaPluginDialogCSS">';
            jQuery(".exe-mind-map", d).each(function (i) {
                var title = $(".title", this);
                title = title.length == 1 ? title.text() : $("img", this).attr("alt");
                // A CSS string that cannot close the rule or the style element
                if (title) s += '.exe-mind-map:nth-of-type(' + (i + 1) + '):before{content:' + JSON.stringify(title).replace(/</g, '\\3c ') + '}';
            });
            s += '</style>';
            jQuery("HEAD", d).append(s);
        },

        activateButton: function (node) {
            var e = jQuery(node);
            if (e.attr("class") == 'exe-mind-map') return true;
            if (e.parents(".exe-mind-map").length > 0) return true;
            return false;
        },

        formatOptions: function () {
            var radio = function (value, text) {
                var checked = eXeMediaPluginDialog.actualFormat == value ? ' checked' : '';
                return '<label class="exe-mindmap-format-option" style="margin-right:1.5em"><input type="radio" name="mindmapFormat" value="' + value + '"' + checked + '> ' + eXeMediaPluginDialog.escapeHtml(text) + '</label>';
            };
            return '<fieldset class="exe-mindmap-format" style="border:0;margin:0;padding:0"><legend class="tox-label">' + eXeMediaPluginDialog.escapeHtml(_('Embed as')) + '</legend>' +
                radio('png', _('Image (PNG)')) + ' ' + radio('svg', _('Diagram (SVG, Mermaid)')) + '</fieldset>';
        },

        selectedFormat: function () {
            var checked = document.querySelector('.tox-dialog input[name="mindmapFormat"]:checked');
            return checked ? checked.value : eXeMediaPluginDialog.actualFormat;
        },

        escapeHtml: function (text) {
            return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
        },

        stripHtml: function (html) {
            var tmp = document.createElement("DIV");
            tmp.innerHTML = html;
            return tmp.textContent || tmp.innerText || "";
        }

    } // Dialog    

    // Plugin button
    editor.ui.registry.addIcon('exemindmap', '<svg xmlns="http://www.w3.org/2000/svg" height="24" viewBox="0 0 24 24" width="24"><path d="M0 0h24v24H0z" fill="none"/><path d="M22 11V3h-7v3H9V3H2v8h7V8h2v10h4v3h7v-8h-7v3h-2V8h2v3z"/></svg>');
    editor.ui.registry.addToggleButton('exemindmap', {
        icon: 'exemindmap',
        tooltip: _('Mind map'),
        onAction: eXeMediaPluginDialog.openDialog,
        onSetup: function (buttonApi) {
            var editorEventCallback = function (eventApi) {
                buttonApi.setActive(eXeMediaPluginDialog.activateButton(eventApi.element));
            };
            editor.on('NodeChange', editorEventCallback);
            return function (buttonApi) {
                editor.off('NodeChange', editorEventCallback);
            }
        }
    });

    editor.on('init', function (e) {
        editor.dom.loadCSS(url + "/css/content.css");
        eXeMediaPluginDialog.showMindMapsTitles(editor);
    });

});